from pathlib import Path
import difflib
p = 'app/service.py'
for before, after, dest in [('candidate/B', '.scratch/U', 'feature.patch'), ('.scratch/U', '.scratch/R', 'security.patch')]:
    a = (Path(before) / p).read_text().splitlines(keepends=True)
    b = (Path(after) / p).read_text().splitlines(keepends=True)
    patch = f'diff --git a/{p} b/{p}\\n' + ''.join(difflib.unified_diff(a, b, fromfile=f'a/{p}', tofile=f'b/{p}'))
    (Path('candidate') / dest).write_text(patch)
